create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.focus_sessions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,task text not null default '',mode text not null check(mode in('focus','short','long')),duration_seconds integer not null check(duration_seconds>0),completed_at timestamptz not null default now());
create table public.sleep_logs (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,slept_at timestamptz not null,woke_at timestamptz not null,quality smallint check(quality between 1 and 5),note text,created_at timestamptz not null default now(),constraint valid_sleep_range check(woke_at>slept_at));
create table public.routines (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,position integer not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table public.routine_checks (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,routine_id uuid not null references public.routines(id) on delete cascade,checked_on date not null default current_date,unique(routine_id,checked_on));
create table public.workout_logs (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,workout_date date not null default current_date,duration_minutes integer check(duration_minutes>0),note text,created_at timestamptz not null default now());
create table public.notes (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null default '',content text not null default '',pinned boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.files (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,storage_path text not null unique,mime_type text,size_bytes bigint check(size_bytes>=0),created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.focus_sessions enable row level security; alter table public.sleep_logs enable row level security; alter table public.routines enable row level security; alter table public.routine_checks enable row level security; alter table public.workout_logs enable row level security; alter table public.notes enable row level security; alter table public.files enable row level security;
create policy "Users manage own profiles" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "Users manage own focus sessions" on public.focus_sessions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own sleep logs" on public.sleep_logs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own routines" on public.routines for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own routine checks" on public.routine_checks for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own workout logs" on public.workout_logs for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own notes" on public.notes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "Users manage own files" on public.files for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public,file_size_limit) values('private-files','private-files',false,52428800) on conflict(id) do nothing;
create policy "Users upload own files" on storage.objects for insert to authenticated with check(bucket_id='private-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Users read own files" on storage.objects for select to authenticated using(bucket_id='private-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Users delete own files" on storage.objects for delete to authenticated using(bucket_id='private-files' and (storage.foldername(name))[1]=auth.uid()::text);
create index focus_sessions_user_completed_idx on public.focus_sessions(user_id,completed_at desc); create index notes_user_updated_idx on public.notes(user_id,updated_at desc); create index workout_logs_user_date_idx on public.workout_logs(user_id,workout_date desc);
